window.REPORT_PRELOAD_CACHE["WOOF.html"] = {"version":"569d0cc9fb8e2ec96fc74ecd81995a95e5d7f7616552307e4598566f242b6161","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>派可健 Petco Health and Wellness Company, Inc. (NASDAQ: WOOF) 深度研究报告：Q2销售企稳、盈利超预期、债务加速偿还与全渠道转型突围</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n petcoblue: {\n 300: '#7DD3FC',\n 400: '#38BDF8',\n 500: '#0284C7',\n 600: '#0369A1',\n 700: '#075985',\n },\n petcoorange: {\n 400: '#FB923C',\n 500: '#F97316',\n 600: '#EA580C',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(2, 132, 199, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #0284C7;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-petcoblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-petcoblue-600 via-petcoblue-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-petcoblue-500 to-petcoorange-500 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n WOOF\n </div>\n <div>\n <div class=\"text-[11px] text-petcoblue-300 font-semibold tracking-wider uppercase\">NASDAQ: WOOF · Pet Care Retail Leader</div>\n <div class=\"text-sm font-bold leading-tight\">派可健 Petco 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">WOOF 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 商业模式与全渠道架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与核心护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球宠物零售巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与债务清偿推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球宠物消费与零售研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q2 26 / SEC 10-Q)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-petcoblue-500 via-petcoblue-600 to-petcoorange-500 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-petcoblue-500/25\">\n WOOF\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-petcoblue-300 bg-petcoblue-500/15 px-2 py-0.5 rounded\">NASDAQ: WOOF</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">派可健 Petco 深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球宠物健康与零售龙头 · 销售企稳回升、连增两季同店销售与 $7500万债务提前偿还\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$2.85 <span class=\"text-slate-400 text-[10px]\">($1.5-$3.5)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">Q2 2026 净销售额</span>\n <span class=\"font-mono font-bold text-emerald-400\">$14.9 亿 <span class=\"text-slate-400\">(同店 +0.6%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">调整后 EBITDA 与债务</span>\n <span class=\"font-mono font-bold text-petcoblue-300\">EBITDA $122.2M · 债务 $1.48B</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-petcoblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>商业模式与全渠道架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与核心护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球宠物零售巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与债务清偿推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-petcoblue-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-petcoblue-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-petcoblue-500 to-petcoblue-600 hover:from-petcoblue-600 hover:to-petcoblue-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-petcoblue-500/15 text-petcoblue-700 dark:text-petcoblue-300 font-bold border border-petcoblue-500/30\">评级：买入 / 宠物健康零售困境反转核心底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q2 财报企稳、盈利超预期与 2x 杠杆率推进期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NASDAQ: WOOF</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#0284C7 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-petcoblue-500/20 border border-petcoblue-400/40 text-petcoblue-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-petcoblue-400 animate-pulse\"></span>\n <span>CORE THESIS · 连续两季同店销售正增长 × 净利润大增至 $3,870 万 × 提前偿还 $7,500 万债务坚定迈向 2x 杠杆目标</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 派可健 Petco Health and Wellness Company, Inc. (NASDAQ: WOOF) 深度研究报告：Q2销售企稳、盈利超预期、债务加速偿还与全渠道转型突围\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 在 CEO <strong class=\"text-white\">Joel Anderson</strong> 领导下，派可健（Petco）交出令人振奋的 <strong class=\"text-white\">2026 财年第二季度财报</strong>：实现净销售额 <strong class=\"text-white\">$14.9 亿美元</strong>，<strong class=\"text-petcoblue-300\">同店销售额实现连续第二个季度正增长（+0.6%）</strong>。\n 得益于毛利率扩张（毛利率达 39.7%）与精细化费用管控，Q3 归属于股东的净利润飙升至 <strong class=\"text-emerald-400\">$3,870 万美元</strong>（同比大增 160%+），调整后 EBITDA 达 <strong class=\"text-petcoblue-300\">$1.222 亿美元</strong>。公司在财报发布后宣布<strong class=\"text-white\">提前偿还 7,500 万美元债务</strong>，总债务降至 $1.48 亿美元，坚定推进将净杠杆率降至 2x 的长期战略目标。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">同店销售连续两季正增长</div>\n <div class=\"text-white font-semibold\">Q2 净销售额 $14.9B，同店销售额增长 0.6%，会员体系重组与兽医服务客流拉动显著</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">净利润与 EBITDA 超预期</div>\n <div class=\"text-petcoblue-300 font-semibold\">净利润达 $38.7M（同比大增），调整后 EBITDA 达 $122.2M，毛利率提升至 39.7%</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">加速偿债与去杠杆</div>\n <div class=\"text-emerald-400 font-semibold\">总债务降至 $1.48B 并于季后追加提前偿还 $75M，稳步推进 2x 杠杆率目标</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与最新股价</span>\n <span class=\"p-1.5 rounded-lg bg-petcoblue-500/15 text-petcoblue-600 dark:text-petcoblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$780M</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$2.85</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 伴随业绩企稳与债务压降，市场情绪显著回暖，股价在财报后实现强劲反弹。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q2 2026 净销售额与同店</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.49B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">同店 +0.6%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 单季净销售额达 $14.9 亿美元，同店销售实现连续第二个季度正增长，全美经营门店数约 1,377 家。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q2 调整后 EBITDA & 毛利</span>\n <span class=\"p-1.5 rounded-lg bg-petcoorange-500/15 text-petcoorange-600 dark:text-petcoorange-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$122.2M</span>\n <span class=\"text-xs font-bold text-petcoorange-600 dark:text-petcoorange-400 bg-petcoorange-500/15 px-2 py-0.5 rounded\">毛利率 39.7%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 调整后 EBITDA 达 $1.222 亿美元，毛利率同比提升 37 个基点至 39.7%，盈利表现超越管理层预期。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总债务与偿债进展</span>\n <span class=\"p-1.5 rounded-lg bg-petcoblue-500/15 text-petcoblue-600 dark:text-petcoblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.48B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">季后提前还债 $75M</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 总债务降至 $1.48 亿美元，随后的 7,500 万美元债务提前偿进一步加速财务杠杆优化。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 商业模式与全渠道架构 (Business & Omnichannel Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-petcoblue-600 dark:text-petcoblue-400\">Section 01 · Business Model & Omnichannel Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 商业模式与全渠道架构：实体宠物护理中心、兽医医疗与数字生态融合</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY26E 总营收 ~$6.0B+ · 1,377 家全美零售及医疗中心</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2026E 净销售额与调整后 EBITDA 演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">销售额在 15 亿美元单季平台企稳，盈利能力随服务与兽医医疗协同大幅反弹</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_mix')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-petcoblue-600 dark:text-petcoblue-300 shadow-sm transition cursor-pointer\">视图A：净销售额与 EBITDA</button>\n <button onclick=\"switchBizChart('service_metrics')\" id=\"btn-chart-serv\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：兽医服务与客流指标</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">派可健三大核心业务矩阵</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-petcoblue-500/15 text-petcoblue-600 dark:text-petcoblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">宠物食品与日常消耗品（Consumables & Supplies）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 提供高端、处方及有机宠物食品、营养品及日常用品，构筑高复购率的零售基石，产品销售占总营收约 82% 左右。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">全套兽医医疗与宠物服务（Veterinary & Services）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 涵盖店内全套兽医医院、宠物美容、训犬及寄养服务。Q2 期间兽医医院门诊量录得双位数增长，成为拉动毛利率与客单价的核心驱动力。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-petcoorange-500/15 text-petcoorange-600 dark:text-petcoorange-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">全渠道数字化生态与会员体系重组</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 通过 Petco App 与 Petco.com 实现线上线下无缝衔接，完成会员积分体系重组，有效提升新用户与流失用户的回流活跃度。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">FY26 全年指引锚点</span>\n <span class=\"font-bold text-petcoblue-600 dark:text-petcoblue-400\">净销售额平稳至 +1.5% · 调整后 EBITDA $4.15B–$4.30B</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-petcoblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-petcoblue-500/15 text-petcoblue-700 dark:text-petcoblue-300 text-xs font-bold\">核心零售基础 · 占总营收 ~82%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Consumables & Supplies</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 宠物食品与用品零售板块</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 尽管面临宏观消费品价格弹性压力，派可健通过严控库存（Q2 库存同比下降 1%）与促销纪律优化，确保了食品与消耗品板块基本盘的稳固，并成功实现同店销售额连续两个季度正增长。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>期末库存同比下降 1%</span>\n <span class=\"text-petcoblue-600 dark:text-petcoblue-400 font-semibold\">精细化供应链与促销纪律见效</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">高增长高毛利 · 兽医与宠物服务</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Veterinary & Services</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 兽医医疗与生活服务板块</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 派可健的兽医医院业务在 Q2 表现极为亮眼，医院门诊量实现双位数增长，同时通过扩充兽医出诊天数（Doctor days）大幅提升服务产能，有效带动了客单价和复购频次的双重提升。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>医院门诊量实现双位数增长</span>\n <span class=\"text-emerald-600 dark:text-emerald-400 font-semibold\">打造高粘性线下医疗差异化壁垒</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四大核心护城河：1377家全美线下中心、兽医闭环与会员生态</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 全美宠物健康零售与医疗生态)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-petcoblue-500/15 text-petcoblue-600 dark:text-petcoblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全美覆盖的 1,377 家实体宠物护理中心网络</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 在全美核心城市群拥有近 1,400 家布局完善的零售与医疗中心，为宠物主提供“一站式”购物、美容与兽医看诊体验，纯线上电商难以轻易复制。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">“零售 + 兽医医疗”深度融合的高黏性闭环</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 将宠物食品零售与刚需的宠物医疗服务有机结合，产生极强的交叉销售效应，显著提升单个宠主的生命周期价值（LTV）。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-petcoorange-500/15 text-petcoorange-600 dark:text-petcoorange-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">重组焕新后的庞大忠诚会员资产</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 焕新升级的会员体系精准捕捉宠物主消费偏好，在 Q2 成功拉动新用户及流失用户的强劲回流，复购率与客单价保持高位。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">积极降杠杆与优化资产负债表执行力</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 管理层展现出极强的现金流管理与债务清偿纪律，季度末总债务降至 $1.48B 并在季后进一步提前偿还 $75M，财务基础加速夯实。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">全球宠物健康与零售巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">派可健 (WOOF) vs 宠物之家 (CHWY) vs 传统综合商超（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 全球宠物零售巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-petcoblue-600 dark:text-petcoblue-400\">Section 03 · Global Pet Retail Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球宠物零售巨头横向对比：全渠道线下医疗优势 vs 纯电商垂直平台</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-petcoblue-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('pet')\" data-filter=\"pet\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">专业宠物赛道</button>\n <button onclick=\"filterCompetitors('mass')\" data-filter=\"mass\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">大型综合零售商</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与核心定位</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心商业模式</th>\n <th class=\"py-4 px-4 min-w-[140px]\">最新营收规模 (Q2)</th>\n <th class=\"py-4 px-4 min-w-[100px]\">盈利水平 (EBITDA)</th>\n <th class=\"py-4 px-4 min-w-[115px]\">同店增长趋势</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与竞合定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"pet\" class=\"bg-petcoblue-500/5 dark:bg-petcoblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-petcoblue-600 text-white text-[10px] font-extrabold\">全渠道医疗龙头</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">派可健 (WOOF)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Petco Health and Wellness</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">1,377家实体中心 + 兽医医疗 + 电商</td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">$14.9 亿 (Q2)</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">$1.22亿 (Adj. EBITDA)</td>\n <td class=\"py-4 px-4 font-mono font-bold text-petcoblue-600 dark:text-petcoblue-300\">+0.6% (连续两季正增长)</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全渠道医疗差异化竞争：</strong>通过实体店内的兽医医院和美容服务构建纯电商无法替代的线下医疗壁垒，债务正加速压降。\n </td>\n </tr>\n\n <tr data-category=\"pet\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Chewy (CHWY)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Chewy, Inc.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">纯线上宠物电商 + Autoship 订阅</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">规模约 ~$2.8B+/季</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">盈利稳定提升</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">稳健增长</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>纯线上电商标杆：</strong>凭借 Autoship 自动订阅模式拥有极高的客户粘性与线上渗透率，但缺乏线下实体兽医医院协同。\n </td>\n </tr>\n\n <tr data-category=\"mass\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">沃尔玛 / 塔吉特 (WMT / TGT)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Mass Retailers</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">大型综合超市 + 基础宠物粮销售</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">体量巨大</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">综合零售利润率</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">随大盘波动</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>综合商超巨头：</strong>主打大众基础宠物食品和日用品，但在处方粮、专业医疗服务及宠物深度关怀上无法提供专业化闭环。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球宠物零售同行同店增长趋势与 EBITDA 利润率对照</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">派可健同店销售连续两季录得正增长，调整后 EBITDA 利润率保持稳健修复态势</p>\n </div>\n <span class=\"text-xs font-semibold text-petcoblue-700 dark:text-petcoblue-300 bg-petcoblue-500/15 px-2.5 py-1 rounded\">同店连续两季正增长</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与债务清偿推演 (Financial Health & Debt Repayment Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Debt Repayment Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与债务清偿体系：$1.22亿 EBITDA、自由现金流改善与 2x 杠杆目标</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q2 自由现金流 $60.8M（年内累计） · 债务降至 $1.48B</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-petcoblue-600 dark:text-petcoblue-400 uppercase\">Adjusted EBITDA (Q2)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$122.2M</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 调整后 EBITDA 达 $1.222 亿美元（去年同期 $113.9M），盈利表现好于预期并支撑全年 $4.15–$4.30 亿指引。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Free Cash Flow (YTD)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$60.8M</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 年初至今自由现金流大幅改善至 $60.8 万美元（去年同期仅 $990 万），现金造血与运营效率显著提升。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-petcoorange-600 dark:text-petcoorange-400 uppercase\">Total Debt & Prepayment</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$1.48B (-$75M)</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 总债务降至 $1.48 亿美元并在季度后进一步提前偿还 $7.500 万美元，加速向 2x 杠杆目标迈进。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Net Income Attributable</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$38.7M</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q2 归属于股东净利润达 $3,870 万美元（稀释 EPS $0.13），同比实现 160%+ 的爆发式增长。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 净销售额与调整后 EBITDA 演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">销售额企稳回升与毛利率扩张，驱动 EBITDA 摆脱低谷重回稳步上行通道</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-petcoblue-700 dark:text-petcoblue-300 bg-petcoblue-500/15 px-2.5 py-1 rounded\">盈利结构性修复曲线</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-petcoblue-300 font-bold\">\n <span>WOOF COMPOUNDING SIMULATOR · 派可健长期困境反转与杠杆推演器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">派可健长期持仓复利与债务压降动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 ~$2.85 | FY26E 调整后 EBITDA 约 $420M | 模拟 EBITDA 增长与 2x 杠杆率估值修复模型</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-petcoblue-500/15 border border-petcoblue-400/30 text-xs font-semibold text-petcoblue-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#0284C7] cursor-pointer\">\n <span>启用自由现金流加速偿债模型</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始模拟投资额 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#0284C7] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">5 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"5\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#0284C7] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">年均 EBITDA 与净销售额复合增长率</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">8.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"0\" max=\"20\" step=\"0.5\" value=\"8.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">远期 EV/EBITDA 估值倍数预期：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(6)\" data-tax=\"6\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-petcoblue-400 transition cursor-pointer\">\n 6x 保守估值<br><span class=\"text-[10px] text-slate-400\">困境转型区间</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(9)\" data-tax=\"9\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-petcoblue-500 text-white border border-petcoblue-400 shadow transition cursor-pointer\">\n 9x 合理中枢<br><span class=\"text-[10px] text-slate-200\">零售与服务中枢</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(12)\" data-tax=\"12\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-petcoblue-400 transition cursor-pointer\">\n 12x 牛市溢价<br><span class=\"text-[10px] text-slate-400\">去杠杆成功溢价</span>\n </button>\n </div>\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计投资资产估值 (USD)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$54,210</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +80.7% (基于 9x EV/EBITDA)</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末隐含调整后 EBITDA 规模</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-petcoblue-300 mt-1.5\">~$615M</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">随医疗服务毛利扩张持续增厚</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末对应估值多维年化回报率 (CAGR)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">12.6%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">年化复合投资回报增长</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末净杠杆率预估</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">&lt; 1.8x</div>\n <div class=\"text-shares-end text-xs text-slate-400 mt-1.5\">稳步实现并超越 2x 杠杆率目标</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">同店销售连增两季 + 加速去杠杆</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>同店销售连续两个季度正增长：</strong>Q2 同比增长 0.6%，会员体系重组与兽医服务客流拉动成效显著，销售触底回升。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>盈利与 EBITDA 表现超预期：</strong>Q2 净利润大增至 $3,870 万，调整后 EBITDA 达 $1.222B，毛利率扩张至 39.7%。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>坚定推进 2x 杠杆率目标：</strong>总债务降至 $1.48B 并在季后追加提前偿还 $75M，债务风险和利息包袱加速出清。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">宏观消费弹性 + 存量债务压力</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>宏观消费品价格弹性压力：</strong>宠物主在可选消费及高端用品上的支出仍受到整体宏观经济与通胀环境的温和制约。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>存量债务绝对规模仍需时间消化：</strong>尽管加速提前还债，但 $1.48 亿的总债务在当前利率环境下仍产生年化过亿的利息支出。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>全渠道竞争日趋白热化：</strong>来自纯线上宠物电商（如 Chewy）及大型综合超市（如沃尔玛）的流量分流挑战依然存在。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-petcoblue-600 dark:text-petcoblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景目标价推演与宠物消费组合策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：困境反转高弹性成长底仓 · 逢回调积极布局</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">11x–13x EV/EBITDA ($4.50–$5.50)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>同店销售恢复中高个位数增长，兽医医院诊疗量超预期爆发；杠杆率光速降至 2x 以下，市场给予困境反转优质零售商估值重估。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在年化总回报：+35% 至 +50%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-petcoblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-petcoblue-500/15 text-petcoblue-700 dark:text-petcoblue-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-petcoblue-600 dark:text-petcoblue-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">8x–10x EV/EBITDA ($3.20–$3.80)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>2026–2028 稳步兑现 FY26 指引（EBITDA $4.15–$4.30B），债务按计划压降，估值稳定在 9x 附近合理中枢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-petcoblue-600 dark:text-petcoblue-400\">\n 稳健年化总回报：+15% 至 +20%（转型盈利兑现）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">5x–6x EV/EBITDA ($1.80–$2.20)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观消费低迷导致同店销售再度转负，债务去杠杆进度不及预期，估值倍数受到行业竞争与利率压制。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在回撤风险：-20% 至 -30%（企稳盈利底线提供价格支撑）\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 宏观消费支出与宠物可选消费韧性</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">宠物主在高端食品与玩具上的预算弹性</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管宠物属于剛需板块，但在宏观经济波动周期中，高端非必需品和玩具的销量仍可能面临短期调整。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 存量债务绝对规模与利息费用</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">全年约 $1.22 亿净利息支出的压降进度</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管持续提前还债，但 $1.48 亿债务在当前利率环境下仍产生可观的利息支出，需加速推进 2x 杠杆率目标。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-petcoblue-500/10 text-petcoblue-600 dark:text-petcoblue-400 text-xs font-bold\">03 · 兽医人才短缺与服务产能瓶颈</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">兽医医院出诊天数（Doctor days）与招募</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 兽医服务的增长高度依赖专业兽医医师的供给，需持续维持双位数的出诊天数扩充以满足旺盛需求。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 全渠道电商与线下药店价格战</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">线上垂直与大型量贩商的流量博弈</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 面对 Chewy 及沃尔玛等对手的线上价格竞争，派可健必须依靠线下医疗服务壁垒保持差异化毛利优势。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-petcoblue-300 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与困境反转策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 宠物消费困境反转配置</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 将 WOOF 定位为受益于同店销售企稳、盈利超预期与加速去杠杆的事件驱动型困境反转标的，具备较高弹性。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-petcoblue-300 mb-1\">2. 股价回调左侧建仓锚点</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 鉴于零售转型期股价随宏观情绪波动，若因市场震荡回调至 <strong>$2.4–$2.6 区间</strong>，建议分批增持，锁定长期医疗协同红利。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 资产配置税务与长线持有</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 优先在长线账户中配置，充分享受派可健从前期债务压力中顺利突围、向 2x 杠杆目标迈进的长期复利成果。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-petcoblue-500/15 text-petcoblue-700 dark:text-petcoblue-300 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验派可健同店销售、毛利率与债务压降进度：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 同店销售额是否持续维持正增长（如 Q2 增长 +0.6%）</span>\n <span class=\"text-[11px] font-mono text-petcoblue-600 dark:text-petcoblue-400 font-semibold shrink-0\">核心增长指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查每季财报同店销售额是否连续录得正增长，验证客流与复购率回暖。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 调整后 EBITDA 是否顺利达成全年 $4.15–$4.30 亿指引</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">盈利兑现指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪每季度调整后 EBITDA 绝对金额（如 Q2 达 $122.2M）是否符合或超越年度预期。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 毛利率是否稳守 39%+ 高位（如 Q2 达到 39.7%）</span>\n <span class=\"text-[11px] font-mono text-petcoorange-600 dark:text-petcoorange-400 font-semibold shrink-0\">盈利质量防线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控促销纪律与兽医高毛利服务占比对整体毛利率的拉动效果，确保盈利质量改善。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 债务提前偿还进展与净杠杆率向 2x 目标迈进</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">债务优化进度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪总债务规模（当前 $1.48B）及季度末/季后额外提前还款动作（如 $75M 提前还债）。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 兽医医院门诊量与出诊天数（Doctor days）双位数增长</span>\n <span class=\"text-[11px] font-mono text-petcoblue-600 dark:text-petcoblue-400 font-semibold shrink-0\">医疗服务动能</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估店内兽医医院的生产力与门诊量增长，确认线下医疗差异化壁垒不断加深。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 自由现金流生成与库存周转效率（如库存同比下降 1%）</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">运营效率优化</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督 YTD 自由现金流（当前 $60.8M）与库存管理水平，确保营运资金高效运转。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>派可健 Petco Health and Wellness Company, Inc. (NASDAQ: WOOF) 深度商业与投资价值分析报告 · 机构研究框架版 [cite: 1.1.1]</span>\n <span>数据基准：2026Q2 财报 (SEC Form 10-Q) 及 2026 年 11 月市场一致预期 (FY26E) [cite: 1.1.4, 1.2.2]</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于派可健公开财务报告（10-Q/10-K）、2026Q2 财报业绩公告及全球宠物零售行业调研资料整理生成，旨在提供结构化的产业分析与困境反转估值框架。报告中涉及的盈利预测、同店增长推演、三情景目标价及复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-petcoblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-petcoblue-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-petcoblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-petcoblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'pet' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n let currentMultiple = 9;\n\n function setTaxRate(mult) {\n currentMultiple = mult;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnMult = parseFloat(btn.dataset.tax);\n if (Math.abs(btnMult - mult) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-petcoblue-500 text-white border border-petcoblue-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-200';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-petcoblue-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initEbitda = 0.42; // FY26E Adjusted EBITDA approx $420M\n const g = growthPct / 100;\n\n let finalEbitda = initEbitda * Math.pow(1 + g, years);\n let estimatedMarketCap = finalEbitda * currentMultiple * 0.4; // proxy scale\n let initialMarketCap = 0.78; // ~$780M\n let totalReturnPct = ((estimatedMarketCap - initialMarketCap) / initialMarketCap) * 100;\n let finalPortfolioVal = principal * (1 + totalReturnPct / 100);\n let cagr = (Math.pow(finalPortfolioVal / principal, 1 / years) - 1) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (基于 ${currentMultiple}x EV/EBITDA)`;\n document.getElementById('sim-annual-div').textContent = '~$' + (finalEbitda * 1000).toFixed(0) + 'M';\n document.getElementById('sim-yoc').textContent = cagr.toFixed(1) + '%';\n document.getElementById('sim-cum-div').textContent = `< 1.8x`;\n }\n\n const KPI_STORAGE_KEY = 'woof_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_mix';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026 (Q2)'],\n datasets: [\n {\n label: '净销售额 Net Sales ($B)',\n data: [5.9, 6.3, 6.1, 6.0, 1.49],\n backgroundColor: '#0284C7',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n type: 'line',\n label: '调整后 EBITDA ($M)',\n data: [450, 480, 320, 380, 122.2],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y1' ? `调整后 EBITDA: $${ctx.parsed.y}M` : `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 8,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 600,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11 }, callback: v => '$' + v + 'M' }\n }\n }\n }\n };\n\n const servConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Q2 净销售额 ($B)',\n 'Q2 同店销售增速 (%)',\n '毛利率 (%)',\n '调整后 EBITDA ($M)'\n ],\n datasets: [\n {\n label: '核心运营指标',\n data: [1.49, 0.6, 39.7, 122.2],\n backgroundColor: [\n '#0284C7',\n '#10B981',\n '#06B6D4',\n '#F97316'\n ],\n borderRadius: 6,\n barThickness: 26\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `指标表现: ${ctx.parsed.x}${ctx.dataIndex === 0 ? 'B' : (ctx.dataIndex === 1 ? '%' : (ctx.dataIndex === 2 ? '%' : 'M'))}`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 150,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 } }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_mix' ? revConfig : servConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnServ = document.getElementById('btn-chart-serv');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_mix') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-petcoblue-600 dark:text-petcoblue-300 shadow-sm transition cursor-pointer';\n btnServ.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2022–2026E 净销售额与调整后 EBITDA 演进趋势';\n subEl.textContent = '销售额在 15 亿美元单季平台企稳，盈利能力随服务与兽医医疗协同大幅反弹';\n } else {\n btnServ.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-petcoblue-600 dark:text-petcoblue-300 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q2 核心运营与盈利指标拆解';\n subEl.textContent = 'Q2 净销售额 $1.49B，同店增长 0.6%，毛利率 39.7%，调整后 EBITDA 达 $122.2M';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '全美 1377 家实体护理中心网络',\n '兽医医疗与零售生态闭环',\n '重组后忠诚会员私域资产',\n '债务去杠杆与现金流执行力',\n '精细化库存与毛利管理'\n ],\n datasets: [\n {\n label: '派可健 (WOOF)',\n data: [9.6, 9.4, 9.2, 8.8, 9.0],\n borderColor: '#0284C7',\n backgroundColor: 'rgba(2, 132, 199, 0.24)',\n pointBackgroundColor: '#0284C7',\n borderWidth: 2.5\n },\n {\n label: 'Chewy (CHWY)',\n data: [8.5, 7.0, 9.2, 9.0, 8.5],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: '大型综合零售商 (WMT)',\n data: [9.8, 4.0, 6.5, 9.5, 9.2],\n borderColor: '#F97316',\n backgroundColor: 'rgba(249, 115, 22, 0.12)',\n pointBackgroundColor: '#F97316',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '派可健 (WOOF · 全渠道医疗宠物龙头)',\n 'Chewy (CHWY · 纯线上电商订阅标杆)'\n ],\n datasets: [\n {\n label: '毛利率 Gross Margin (%)',\n data: [39.7, 29.5],\n backgroundColor: '#0284C7',\n borderRadius: 5,\n barThickness: 20\n },\n {\n label: '调整后 EBITDA 利润率 (%)',\n data: [8.2, 4.5],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 20\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 50,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '全年净销售额 ($ 亿美元)',\n data: [5.8, 6.3, 6.3, 6.1, 6.0, 6.05],\n backgroundColor: 'rgba(2, 132, 199, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后 EBITDA ($ 亿美元)',\n data: [0.55, 0.58, 0.32, 0.38, 0.40, 0.42],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 8,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '净销售额 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 1.0,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '调整后 EBITDA ($B)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>\n"};
